<?php require "config/db.php";require_login();if(($_SESSION["user"]["role"]??"")!=="admin"){http_response_code(403);die("Access denied. Admin account required.");}if(isset($_POST["status"],$_POST["order_id"])){$allowed=["Placed","Preparing","Out for delivery","Delivered","Cancelled"];if(in_array($_POST["status"],$allowed,true)){$s=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$s->execute([$_POST["status"],(int)$_POST["order_id"]]);}}$orders=$pdo->query("SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC")->fetchAll(); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin | Foody Spot</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/nav.php"; ?><main class="container page"><div class="page-head"><span class="eyebrow">MANAGEMENT</span><h1>Order dashboard<span>.</span></h1></div><?php foreach($orders as $o): ?><section class="order-card"><div><b>Order #<?= (int)$o["id"] ?> · <?= h($o["customer_name"]) ?></b><p><?= h($o["email"]) ?> · <?= h($o["phone"]) ?></p><small><?= h($o["address"]) ?></small></div><div class="order-right"><strong>₹<?= number_format($o["total"],2) ?></strong><form method="post"><input type="hidden" name="order_id" value="<?= (int)$o["id"] ?>"><select name="status"><?php foreach(["Placed","Preparing","Out for delivery","Delivered","Cancelled"] as $st): ?><option <?= $o["status"]===$st?"selected":"" ?>><?= h($st) ?></option><?php endforeach; ?></select><button class="add-btn">Update</button></form></div></section><?php endforeach; ?></main><?php include "includes/footer.php"; ?></body></html>